 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#04a3e1;font-size:5.45vh;font-family:'Bebas Neue Bold';\"><U> </U></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:3.31vh;font-family:'Oswald';\"><B><I>Welcome to Your Dream Home | 360\u00b0 Virtual Tour</I></B></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.58vh;font-family:'Oswald';\"><I>Step inside your dream home with our immersive 360\u00b0 virtual experience.</I></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.58vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.58vh;font-family:'Oswald';\"><I>Explore every corner of your beautifully designed residence, featuring elegant interiors, thoughtfully planned spaces, modern finishes, and functional design.</I></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.58vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.58vh;font-family:'Oswald';\"><I>Navigate through each room to discover the design, colours, materials, and details from every angle.</I></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.58vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.58vh;font-family:'Oswald';\"><I>Your Home. Your Style. Your Vision</I></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-family:'Oswald';\"><B><I>Note: 3D visuals are for design representation. Actual finishes and materials may vary.</I></B></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.74vh;\"><B>Designed by <BR/></B></SPAN><SPAN STYLE=\"font-size:1.5vh;\">Yash Pratap Singh <BR/>Interior Designer<BR/>Mob:- 9026194208</SPAN><SPAN STYLE=\"color:#ffffff;font-size:1.03vh;font-family:'Oswald Regular';\"><I>Mob.: 9026194208</I></SPAN><SPAN STYLE=\"font-size:1.5vh;\"><BR/></SPAN><SPAN STYLE=\"color:#ffffff;font-size:1.03vh;font-family:'Oswald Regular';\"><I>Mob.: 902619 </I></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:1.03vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:1.74vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:1.74vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.03vh;font-family:Arial, Helvetica, sans-serif;\"/></p></div>",
